 if receipt->>'project' is distinct from 'qvplwejffhjvxaypmjut' or receipt->>'batch' is distinct from 'nl-followup-005-20261031' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact manifest receipt required';end if;
