do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'qvplwejffhjvxaypmjut' or receipt->>'batch' is distinct from 'nl-followup-005-20261031' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>60 then raise exception 'Exact first committed receipt required';end if;
